import numpy as np
from PIL import Image
import os, itertools, json

IN="/tmp_workspace/input"
names=[f"piece_{i:02d}.png" for i in range(1,16)]
imgs={}
for n in names:
    imgs[n]=np.asarray(Image.open(os.path.join(IN,n)).convert("RGB")).astype(np.float64)

def rot_cw(a,k):
    # rotate clockwise by k*90
    return np.rot90(a,(-k)%4)

# oriented tiles: (name,k) -> array
orient={}
for n in names:
    for k in range(4):
        orient[(n,k)]=rot_cw(imgs[n],k)

def edges(a):
    return {
      'top':a[0,:,:],'bottom':a[-1,:,:],'left':a[:,0,:],'right':a[:,-1,:],
      'top2':a[1,:,:],'bottom2':a[-2,:,:],'left2':a[:,1,:],'right2':a[:,-2,:]
    }

E={key:edges(v) for key,v in orient.items()}

def hcost(a,b):
    # a left, b right : a.right vs b.left with gradient prediction
    ea=E[a]; eb=E[b]
    pred_b = ea['right'] + (ea['right']-ea['right2'])
    pred_a = eb['left'] + (eb['left']-eb['left2'])
    c = np.abs(eb['left']-pred_b).sum()+np.abs(ea['right']-pred_a).sum()
    return c

def vcost(a,b):
    # a top(above), b bottom(below): a.bottom vs b.top
    ea=E[a]; eb=E[b]
    pred_b = ea['bottom'] + (ea['bottom']-ea['bottom2'])
    pred_a = eb['top'] + (eb['top']-eb['top2'])
    c = np.abs(eb['top']-pred_b).sum()+np.abs(ea['bottom']-pred_a).sum()
    return c

keys=list(orient.keys())
# Find best matches per direction to explore gap
Hpairs=[]
for a in keys:
    for b in keys:
        if a[0]==b[0]: continue
        Hpairs.append((hcost(a,b),a,b))
Hpairs.sort()
print("Top horizontal (a-left | b-right):")
for c,a,b in Hpairs[:20]:
    print(f"{c:9.0f}  {a[0]} r{a[1]} | {b[0]} r{b[1]}")

import numpy as np
from PIL import Image
import os, json

IN="/tmp_workspace/input"
names=[f"piece_{i:02d}.png" for i in range(1,16)]
imgs={}
for n in names:
    imgs[n]=np.asarray(Image.open(os.path.join(IN,n)).convert("RGB")).astype(np.float64)

def rot_cw(a,k): return np.rot90(a,(-k)%4)

orient={}
for n in names:
    for k in range(4):
        orient[(n,k)]=rot_cw(imgs[n],k)

def edges(a):
    return {'top':a[0],'bottom':a[-1],'left':a[:,0],'right':a[:,-1],
            'top2':a[1],'bottom2':a[-2],'left2':a[:,1],'right2':a[:,-2]}
E={key:edges(v) for key,v in orient.items()}

Hcache={}; Vcache={}
def hcost(a,b):
    key=(a,b)
    if key in Hcache: return Hcache[key]
    ea=E[a]; eb=E[b]
    pb=ea['right']+(ea['right']-ea['right2']); pa=eb['left']+(eb['left']-eb['left2'])
    c=np.abs(eb['left']-pb).sum()+np.abs(ea['right']-pa).sum(); Hcache[key]=c; return c
def vcost(a,b):
    key=(a,b)
    if key in Vcache: return Vcache[key]
    ea=E[a]; eb=E[b]
    pb=ea['bottom']+(ea['bottom']-ea['bottom2']); pa=eb['top']+(eb['top']-eb['top2'])
    c=np.abs(eb['top']-pb).sum()+np.abs(ea['bottom']-pa).sum(); Vcache[key]=c; return c

keys=list(orient.keys())
BEAM=800
# state: (cost, tuple_of_placed_keys, frozenset_used_names)
states=[(0.0,(k,),frozenset([k[0]])) for k in keys]
for p in range(1,9):
    row,col=divmod(p,3)
    new=[]
    for cost,placed,used in states:
        for n in names:
            if n in used: continue
            for kk in range(4):
                cand=(n,kk)
                inc=0.0
                if col>0:
                    inc+=hcost(placed[p-1],cand)
                if row>0:
                    inc+=vcost(placed[p-3],cand)
                new.append((cost+inc,placed+(cand,),used|{n}))
    new.sort(key=lambda x:x[0])
    states=new[:BEAM]
best=states[0]
print("best total cost",best[0])
for i in range(3):
    print([f"{best[1][i*3+j][0]} r{best[1][i*3+j][1]}" for j in range(3)])
# save
with open("/tmp_workspace/best.json","w") as f:
    json.dump([[list(x[0].split('_')),x[1]] if False else [x[0],x[1]] for x in best[1]],f)
import pickle
pickle.dump(best,open("/tmp_workspace/best.pkl","wb"))

